package com.lebzlon.measurementtracker.repository; import com.lebzlon.measurementtracker.entity.*; import org.springframework.data.jpa.repository.*; import java.time.Instant; import java.util.*; public interface MeterReadingRepository extends JpaRepository<MeterReading,Long>{List<MeterReading> findByMeterUserOrderByTimestampDesc(User user); Optional<MeterReading> findByIdAndMeterUser(Long id, User user); List<MeterReading> findByMeterIdAndMeterUserOrderByTimestampDesc(Long meterId, User user); @Query("select r from MeterReading r where r.meter.id=:meterId and r.meter.user=:user and r.timestamp between :from and :to order by r.timestamp") List<MeterReading> history(Long meterId, User user, Instant from, Instant to);}